package glitch

import data.glitch_lib

credential_fields := {
    "password", "passwd", "pwd", "secret", "token", "key", "api_key", "apikey",
    "access_key", "secret_key", "private_key", "certificate", "cert",
    "connection_string", "conn_str", "dsn", "uri", "url", "endpoint",
    "database_url", "jdbc_url", "mongodb_uri",
    "auth", "authentication", "credentials", "login", "username", "user",
    "identity", "principal", "service_account",
    "ssh_key", "ssh_private_key", "tls_key", "ssl_key", "signing_key",
    "encryption_key", "decryption_key", "master_key", "kek",
    "registry_auth", "docker_config", "image_pull_secret", "container_registry",
    "access_key_id", "secret_access_key", "account_key", "subscription_id",
    "tenant_id", "client_secret", "service_principal",
    "smtp_password", "email_password", "webhook_secret", "slack_token",
    "db_password", "database_password", "redis_password", "postgres_password",
    "admin_password", "root_password", "default_password", "initial_password"
}

is_credential_field(name) {
    lower_name := lower(name)
    credential_fields[lower_name]
}

private_key_patterns := [
    "-----BEGIN RSA PRIVATE KEY-----",
    "-----BEGIN OPENSSH PRIVATE KEY-----",
    "-----BEGIN PRIVATE KEY-----",
    "-----BEGIN EC PRIVATE KEY-----",
    "-----BEGIN DSA PRIVATE KEY-----"
]

connection_string_pattern := "^(?:[a-z]+://)?[^:]+:[^@]+@.+$"

base64_pattern := "^[A-Za-z0-9+/]{20,}={0,2}$"

known_weak_passwords := {"password", "123456", "admin", "changeme", "secret", "default"}

is_hardcoded_value(value) {
    value.ir_type == "String"
    count(value.value) > 0
    not glitch_lib.has_variable_reference(value)
}

contains_private_key(value) {
    value.ir_type == "String"
    pattern := private_key_patterns[_]
    contains(value.value, pattern)
}

contains_embedded_credentials(value) {
    value.ir_type == "String"
    regex.match(connection_string_pattern, value.value)
}

looks_like_encoded_secret(value) {
    value.ir_type == "String"
    regex.match(base64_pattern, value.value)
}

is_known_weak_password(value) {
    value.ir_type == "String"
    lower_val := lower(value.value)
    known_weak_passwords[lower_val]
}

check_credential_attribute(attr) {
    is_credential_field(attr.name)
    is_hardcoded_value(attr.value)
} else {
    is_credential_field(attr.name)
    attr.value.ir_type == "Hash"
    has_hardcoded_credential_in_hash(attr.value)
} else {
    is_credential_field(attr.name)
    attr.value.ir_type == "Array"
    has_hardcoded_credential_in_array(attr.value)
}

has_hardcoded_credential_in_hash(hash_node) {
    walk(hash_node.value, [_, v])
    v.ir_type == "String"
    is_hardcoded_value(v)
} else {
    walk(hash_node.value, [_, v])
    contains_private_key(v)
} else {
    walk(hash_node.value, [_, v])
    contains_embedded_credentials(v)
}

has_hardcoded_credential_in_array(array_node) {
    walk(array_node.value, [_, v])
    v.ir_type == "String"
    is_hardcoded_value(v)
} else {
    walk(array_node.value, [_, v])
    contains_private_key(v)
}

check_deep_value(value) {
    is_hardcoded_value(value)
    looks_like_encoded_secret(value)
} else {
    contains_private_key(value)
} else {
    contains_embedded_credentials(value)
} else {
    is_known_weak_password(value)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    check_credential_attribute(attr)

    result := {
        "type": "sec_hard_secr",
        "element": attr,
        "path": parent.path,
        "description": "Use of hard-coded credentials - Hard-coded credentials in source code can lead to security vulnerabilities. Use external secret management systems. (CWE-798)"
    }
}

