package glitch

import data.glitch_lib

credential_keywords := [
    "password", "passwd", "pwd", "secret", "token", "api_key", "apikey",
    "access_key", "secret_key", "private_key", "certificate", "cert",
    "credentials", "auth", "login", "ssh_key", "ssl_key", "signing_key",
    "encryption_key", "decryption_key", "master_key", "kek", "client_secret",
    "smtp_password", "email_password", "db_password", "redis_password",
    "postgres_password", "mysql_password", "initial_password", "default_password",
    "admin_password", "root_password", "sha512_password", "sha256_password",
    "md5_password", "webhook_secret", "slack_token", "pagerduty_key",
    "image_pull_secret", "registry_auth", "connection_string", "dsn"
]

non_credential_keywords := {
    "url", "uri", "host", "server", "endpoint", "port", "path", "file",
    "dir", "directory", "name", "id", "type", "method", "mode", "enabled",
    "default", "description", "comment", "timeout", "retries", "user",
    "username", "user_name", "user_id", "group", "version", "format",
    "protocol", "scheme", "domain", "scheme"
}

key_auth_context_values := {"key", "token", "secret", "password"}

contains_credential_keyword(name) {
    lower_name := lower(name)
    keyword := credential_keywords[_]
    contains(lower_name, keyword)
}

is_likely_secret_value(val) {
    count(val) > 0
    not regex.match("^\\s*$", val)
    not regex.match("^\\{\\{", val)
    not regex.match("\\$\\{", val)
    not regex.match("^<%", val)
    not regex.match("^__", val)
    not regex.match("ENC\\[", val)
    not regex.match("^(TODO|FIXME|YOUR[_-].*|CHANGE[_-].*|EXAMPLE|DUMMY|TEST|PLACEHOLDER|INSERT|REPLACE|N/A|NA|NONE|NULL)$", lower(val))
}

matches_hash_entry(node) = result {
    node.ir_type == "Hash"
    entry := node.value[_]
    result := {
        "key_node": entry.key,
        "val_node": entry.value,
        "key": entry.key.value,
        "value": entry.value.value,
        "parent": node
    }
}

hash_has_auth_context(parent_hash) {
    sibling := parent_hash.value[_]
    sibling.key.ir_type == "String"
    sibling.value.ir_type == "String"
    lower(sibling.key.value) == "method"
    {lower(sibling.value.value)} & key_auth_context_values != set()
} else {
    sibling := parent_hash.value[_]
    sibling.key.ir_type == "String"
    sibling.value.ir_type == "String"
    {lower(sibling.key.value)} & {"auth", "authentication", "type"} != set()
    {lower(sibling.value.value)} & key_auth_context_values != set()
}

is_special_credential_key(key_str, parent_hash) {
    lower(key_str) == "key"
    hash_has_auth_context(parent_hash)
}

is_special_credential_key(key_str, parent_hash) {
    contains_credential_keyword(key_str)
    not {lower(key_str)} & non_credential_keywords != set()
}

has_secret_value_pattern(val) {
    # Base64 pattern
    regex.match("^[A-Za-z0-9+/]{20,}={0,2}$", val)
} else {
    # Crypt hash pattern (SHA512, SHA256, MD5, bcrypt)
    regex.match("^\\$[0-9a-zA-Z]+\\$", val)
} else {
    # High entropy string (alphanumeric with mixed case and special chars)
    regex.match("^[A-Za-z0-9_!@#$%^&*()\\-=+\\[\\]{}|;':\\\",./<>?]{8,}$", val)
} else {
    # Simple secret that's not obviously a template or variable
    is_likely_secret_value(val)
}

should_detect_credential(entry) {
    contains_credential_keyword(entry.key)
    entry.val_node.ir_type == "String"
    is_likely_secret_value(entry.value)
} else {
    is_special_credential_key(entry.key, entry.parent)
    entry.val_node.ir_type == "String"
    is_likely_secret_value(entry.value)
}

# Walk all values recursively to find nested hashes
walk_values_for_hashes(node, path, acc) = result {
    node.ir_type == "Hash"
    entry := node.value[_]
    new_path := array.concat(path, [entry.key.value])
    result := array.concat(
        [{
            "key_path": new_path,
            "key_node": entry.key,
            "val_node": entry.value,
            "key": entry.key.value,
            "value": entry.value.value,
            "parent": node,
            "root_type": "hash"
        }],
        walk_values_for_hashes(entry.value, new_path, [])
    )
} else {
    node.ir_type == "Array"
    item := node.value[_]
    result := walk_values_for_hashes(item, path, [])
} else {
    result := []
}

# Collect all hash entries from any node
collect_hash_entries(root) = entries {
    entries := {e |
        walk(root, [_, node])
        node.ir_type == "Hash"
        entry := node.value[_]
        e := {
            "key_node": entry.key,
            "val_node": entry.value,
            "key": entry.key.value,
            "value": entry.value.value,
            "parent": node
        }
    }
}

# Check if variable name path contains credential keyword
path_contains_credential(path_parts) {
    part := path_parts[_]
    contains_credential_keyword(part)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    # Direct string value with credential keyword in name
    var.value.ir_type == "String"
    val_str := var.value.value

    contains_credential_keyword(var.name)
    is_likely_secret_value(val_str)

    result := {
        "type": "sec_hard_secr",
        "element": var,
        "path": parent.path,
        "description": "Use of hard-coded credentials - Hard-coded credentials in source code can lead to security vulnerabilities. Use external secret management systems. (CWE-798)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Get all hash entries from variables
    var := parent.variables[_]

    # Collect nested hash entries
    entry := collect_hash_entries(var.value)[_]

    # Must be a string value that looks like a secret
    entry.val_node.ir_type == "String"
    should_detect_credential(entry)

    result := {
        "type": "sec_hard_secr",
        "element": entry.val_node,
        "path": parent.path,
        "description": "Use of hard-coded credentials - Hard-coded credentials in source code can lead to security vulnerabilities. Use external secret management systems. (CWE-798)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
