is_likely_secret_value(val) {
    count(val) > 0
    not regex.match("^\\s*$", val)
    not regex.match("^\\{\\{", val)
    not regex.match("\\$\\{", val)
    not regex.match("^<%", val)
    not regex.match("^__", val)
